import React, { useState, useEffect } from 'react';
import api from './api';
import { useLiquidGlass } from './hooks/useLiquidGlass';
import AuthModal from './components/AuthModal';
import InteractiveSeating from './components/InteractiveSeating';
import GateSimulator from './components/GateSimulator';
import OrganizerStudio from './components/OrganizerStudio';
import AdminFleetMonitor from './components/AdminFleetMonitor';
import ThemeSwitch from './components/ThemeSwitch';

function App() {
    const [darkMode, setDarkMode] = useState(() => {
        const saved = localStorage.getItem('tf_theme');
        return saved ? saved === 'dark' : true;
    });

    const [user, setUser] = useState(() => {
        const saved = localStorage.getItem('tf_user');
        return saved ? JSON.parse(saved) : null;
    });
    const [activeTab, setActiveTab] = useState('catalog');
    const [events, setEvents] = useState([]);
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [tickets, setTickets] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [toasts, setToasts] = useState([]);

    useEffect(() => {
        const root = document.documentElement;
        if (darkMode) {
            root.classList.add('dark');
            localStorage.setItem('tf_theme', 'dark');
        } else {
            root.classList.remove('dark');
            localStorage.setItem('tf_theme', 'light');
        }
    }, [darkMode]);

    const { rootRef: navRootRef } = useLiquidGlass([user?.id, activeTab, tickets.length, darkMode], {
        cornerRadius: 999,
        refraction: 0.78,
        blurAmount: 0.25,
    });

    const { rootRef: heroRootRef } = useLiquidGlass([user?.id, activeTab, selectedEvent?.id, darkMode], {
        cornerRadius: 32,
        refraction: 0.75,
        blurAmount: 0.22,
    });

    const showToast = (message, type = 'info') => {
        const id = Date.now();
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
    };

    const fetchEvents = async () => {
        try {
            const res = await api.get('/events');
            setEvents(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    const fetchTickets = async () => {
        if (!user) return;
        try {
            const res = await api.get('/tickets/my');
            setTickets(res.data);
        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (user) {
            fetchEvents();
            fetchTickets();
        }
    }, [user]);

    const handleLogout = () => {
        localStorage.removeItem('tf_token');
        localStorage.removeItem('tf_user');
        setUser(null);
        setSelectedEvent(null);
        setActiveTab('catalog');
    };

    if (!user) {
        return (
            <>
                <AuthModal
                    onAuthSuccess={(u) => setUser(u)}
                    showToast={showToast}
                    darkMode={darkMode}
                    onToggleDarkMode={() => setDarkMode(!darkMode)}
                />
                <ToastContainer toasts={toasts} />
            </>
        );
    }

    const filteredEvents = events.filter(ev => {
        const matchesCat = selectedCategory === 'All' || ev.category === selectedCategory;
        const matchesQuery =
            ev.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            ev.venue.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCat && matchesQuery;
    });

    return (
        <div className="min-h-screen flex flex-col relative text-slate-900 dark:text-white transition-colors duration-300">
            <div className="fixed inset-0 pointer-events-none z-0 lg-backdrop-mesh" />

            <header className="sticky top-4 z-40 px-4 sm:px-6 lg:px-8">
                <div ref={navRootRef} className="max-w-6xl mx-auto relative">
                    <div className="lg-backdrop-mesh rounded-full opacity-60" />
                    <div className="lg-surface rounded-full px-5 py-2.5 flex flex-wrap items-center justify-between gap-3 bg-white/70 dark:bg-transparent">
                        <button
                            onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                            className="flex items-center gap-2.5 text-left"
                        >
                            <span className="font-bold text-base tracking-tight text-slate-900 dark:text-white">TicketFlow</span>
                        </button>

                        <nav className="flex items-center gap-1 clean-well p-1 rounded-full">
                            <button
                                onClick={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                                className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                    activeTab === 'catalog'
                                        ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-950 shadow-sm'
                                        : 'text-slate-600 dark:text-white/70 hover:text-slate-950 dark:hover:text-white'
                                }`}
                            >
                                Explore
                            </button>
                            <button
                                onClick={() => setActiveTab('tickets')}
                                className={`flex items-center gap-1.5 px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                    activeTab === 'tickets'
                                        ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-950 shadow-sm'
                                        : 'text-slate-600 dark:text-white/70 hover:text-slate-950 dark:hover:text-white'
                                }`}
                            >
                                <span>Wallet</span>
                                <span className={`text-[10px] font-mono px-1.5 rounded-full ${
                                    activeTab === 'tickets'
                                        ? 'bg-white/20 text-white dark:bg-slate-950/15 dark:text-slate-950'
                                        : 'bg-slate-900/10 text-slate-800 dark:bg-white/15 dark:text-white'
                                }`}>
                  {tickets.length}
                </span>
                            </button>
                            {(user.role === 'ORGANIZER' || user.role === 'ADMIN') && (
                                <button
                                    onClick={() => setActiveTab('organizer')}
                                    className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                        activeTab === 'organizer'
                                            ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-950 shadow-sm'
                                            : 'text-slate-600 dark:text-white/70 hover:text-slate-950 dark:hover:text-white'
                                    }`}
                                >
                                    Studio
                                </button>
                            )}
                            {user.role === 'ADMIN' && (
                                <button
                                    onClick={() => setActiveTab('admin')}
                                    className={`px-4 py-1.5 rounded-full text-xs font-semibold transition ${
                                        activeTab === 'admin'
                                            ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-950 shadow-sm'
                                            : 'text-slate-600 dark:text-white/70 hover:text-slate-950 dark:hover:text-white'
                                    }`}
                                >
                                    Fleet
                                </button>
                            )}
                        </nav>

                        <div className="flex items-center gap-3">
                            <ThemeSwitch darkMode={darkMode} onToggle={() => setDarkMode(!darkMode)} />

                            <span className="hidden md:inline text-xs text-slate-600 dark:text-white/70 font-medium">{user.fullName}</span>
                            <button
                                onClick={handleLogout}
                                className="px-3.5 py-1.5 rounded-full bg-slate-900/10 hover:bg-slate-900/15 dark:bg-white/10 dark:hover:bg-white/20 text-xs font-semibold text-slate-900 dark:text-white transition"
                            >
                                Sign Out
                            </button>
                        </div>
                    </div>
                </div>
            </header>

            <ToastContainer toasts={toasts} />

            <main className="relative z-10 flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {activeTab === 'catalog' && !selectedEvent && (
                    <div className="space-y-8">
                        <div ref={heroRootRef} className="relative">
                            <div className="lg-backdrop-mesh rounded-[32px] opacity-80" />
                            <div className="lg-surface rounded-[32px] p-8 sm:p-10 flex flex-col lg:flex-row lg:items-center justify-between gap-6 bg-white/70 dark:bg-transparent">
                                <div className="max-w-xl space-y-2">
                                    <p className="text-xs font-mono uppercase tracking-widest text-sky-600 dark:text-sky-300 font-semibold">Spatial Ticketing</p>
                                    <h1 className="text-3xl sm:text-4xl font-bold tracking-tight text-slate-900 dark:text-white">
                                        Live Events. Seamless Entry.
                                    </h1>
                                    <p className="text-sm text-slate-600 dark:text-white/65 leading-relaxed">
                                        Select exact seats, store cryptographic passes in your Wallet, and walk straight through optical gates.
                                    </p>
                                </div>

                                <div className="w-full lg:w-80 space-y-3">
                                    <input
                                        type="text"
                                        value={searchQuery}
                                        onChange={(e) => setSearchQuery(e.target.value)}
                                        placeholder="Search events or venues..."
                                        className="w-full px-4 py-2.5 rounded-full clean-well text-sm text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-white/40 focus:outline-none"
                                    />
                                    <div className="flex flex-wrap gap-1.5">
                                        {['All', 'Concerts', 'Festivals', 'Theater', 'Comedy'].map(cat => (
                                            <button
                                                key={cat}
                                                onClick={() => setSelectedCategory(cat)}
                                                className={`px-3 py-1 rounded-full text-xs font-semibold transition ${
                                                    selectedCategory === cat
                                                        ? 'bg-slate-900 text-white dark:bg-white dark:text-slate-950'
                                                        : 'bg-slate-900/10 text-slate-700 hover:bg-slate-900/15 dark:bg-white/10 dark:text-white/75 dark:hover:bg-white/20'
                                                }`}
                                            >
                                                {cat}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {filteredEvents.map(ev => (
                                <div key={ev.id} className="clean-glass-card rounded-[28px] p-7 flex flex-col justify-between gap-6">
                                    <div className="space-y-3">
                                        <div className="flex items-center justify-between text-xs">
                                            <span className="px-3 py-1 rounded-full bg-slate-900/10 dark:bg-white/10 font-semibold text-slate-900 dark:text-white">{ev.category}</span>
                                            <span className="font-mono font-semibold text-emerald-600 dark:text-emerald-300">{ev.totalCapacity - ev.soldCount} seats left</span>
                                        </div>
                                        <h3 className="text-xl font-bold tracking-tight text-slate-900 dark:text-white">{ev.title}</h3>
                                        <div className="text-xs text-slate-600 dark:text-white/60 space-y-0.5">
                                            <p>{ev.venue}</p>
                                            <p className="font-mono text-slate-500 dark:text-white/45">{ev.date}</p>
                                        </div>
                                    </div>

                                    <div className="pt-4 border-t border-slate-900/10 dark:border-white/10 flex items-center justify-between">
                                        <div>
                                            <p className="text-[11px] text-slate-500 dark:text-white/45">From</p>
                                            <p className="text-lg font-bold font-mono text-slate-900 dark:text-white">{ev.gaPrice} RON</p>
                                        </div>
                                        <button onClick={() => setSelectedEvent(ev)} className="px-5 py-2.5 rounded-full apple-pill font-bold text-xs">
                                            Select Seats
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {activeTab === 'catalog' && selectedEvent && (
                    <InteractiveSeating
                        event={selectedEvent}
                        user={user}
                        onBack={() => { setSelectedEvent(null); fetchEvents(); }}
                        onCheckoutSuccess={() => {
                            setSelectedEvent(null);
                            fetchEvents();
                            fetchTickets();
                            setActiveTab('tickets');
                        }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'tickets' && (
                    <GateSimulator
                        tickets={tickets}
                        onRefreshTickets={fetchTickets}
                        onBuyMore={() => { setSelectedEvent(null); setActiveTab('catalog'); }}
                        showToast={showToast}
                    />
                )}

                {activeTab === 'organizer' && (
                    <OrganizerStudio events={events} onEventCreated={fetchEvents} showToast={showToast} />
                )}

                {activeTab === 'admin' && (
                    <AdminFleetMonitor showToast={showToast} />
                )}
            </main>
        </div>
    );
}

const ToastContainer = ({ toasts }) => (
    <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2 max-w-xs w-full pointer-events-none px-4 sm:px-0">
        {toasts.map(t => (
            <div key={t.id} className="pointer-events-auto clean-glass-card px-4 py-3 rounded-full text-xs font-semibold text-slate-900 dark:text-white shadow-2xl flex items-center gap-2.5">
        <span className={`w-2 h-2 rounded-full shrink-0 ${
            t.type === 'success' ? 'bg-emerald-500' : t.type === 'error' ? 'bg-rose-500' : 'bg-sky-500'
        }`} />
                <p>{t.message}</p>
            </div>
        ))}
    </div>
);

export default App;
